// MutateRole changes a stored role in place.
func (f *fakeNexus) MutateRole(id string, fn func(role map[string]any)) {
	f.mu.Lock()
	defer f.mu.Unlock()
	role, ok := f.roles[id]
	if !ok {
		f.t.Fatalf("fake Nexus: no role %q to mutate", id)
	}
