		if !ok {
			t.Fatal("user bench-pull missing")
		}
		if u.Status != "active" || !slices.Equal(u.Roles, []string{"bench-docker-pull"}) {
			t.Errorf("bench-pull = status %q roles %v, want active with bench-docker-pull", u.Status, u.Roles)
		}
