	data, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20+1))
	if len(data) > 1<<20 {
		return resp.StatusCode, &BenchError{Kind: ProvisionFailed, Cause: op + ": body too large", Check: "kubectl logs", Err: &APIError{op, resp.StatusCode}}
	}
	if resp.StatusCode >= 300 && resp.StatusCode != 404 {
		ae := &APIError{op, resp.StatusCode}
		return resp.StatusCode, &BenchError{Kind: ProvisionFailed, Cause: ae.Error(), Check: "kubectl logs", Err: ae}
	}
	if out != nil && resp.StatusCode < 300 && len(bytes.TrimSpace(data)) > 0 {
		if err := json.Unmarshal(data, out); err != nil {
			return resp.StatusCode, err
		}
	}
	return resp.StatusCode, nil
}

func genPW() string {
	const al = "REDACTED"
	b := make([]byte, 32)
	r := make([]byte, 32)
	rand.Read(r)
	for i := range b {
		b[i] = al[int(r[i])%len(al)]
	}
	return string(b)
}

func Provision(ctx context.Context, baseURL string, ip InitialPassword, store SecretStore, p Params, out io.Writer) (ProvisionResult, error) {
	sec, _, err := store.Load()
	if err != nil {
		return ProvisionResult{}, err
	}
	var c *client
	try := func(pw string) (bool, error) {
		if pw == "" {
			return false, nil
		}
		cc := newClient(baseURL, "admin", pw)
		var users []map[string]any
		st, err := cc.do(ctx, "read admin", "GET", pathUsers+"?userId=admin", "", nil, &users)
		if st == 401 || st == 403 {
			return false, nil
		}
		if err != nil {
			if be, ok := err.(*BenchError); ok && be.Kind == ProvisionFailed {
				var ae *APIError
				if errors.As(err, &ae) && ae.Status == 401 {
					return false, nil
				}
			}
			return false, err
		}
		c = cc
		return true, nil
	}
	ok, err := try(sec.AdminPassword)
	if err != nil {
		return ProvisionResult{}, err
	}
	if !ok {
		if ok, err = try(REDACTED); err != nil {
			return ProvisionResult{}, err
		}
		if ok {
			sec.AdminPassword, REDACTED = REDACTED, ""
			if err := store.Save(sec); err != nil {
				return ProvisionResult{}, err
			}
		}
	}
	if !ok {
		initial, have, err := ip.Read(ctx)
		if err != nil {
			return ProvisionResult{}, err
		}
		if !have {
			return ProvisionResult{}, &BenchError{Kind: ProvisionFailed, Cause: "the bench admin password is unknown", Check: "mise run nexus-bench:down, then up"}
		}
		ic := newClient(baseURL, "admin", initial)
		REDACTED := REDACTED
		if REDACTED == "" {
			REDACTED = genPW()
		}
		REDACTED = REDACTED
		if err := store.Save(sec); err != nil {
			return ProvisionResult{}, err
		}
		if _, err := ic.do(ctx, "change admin password", "PUT", pathAdminPassword, "text/plain", REDACTED, nil); err != nil {
			return ProvisionResult{}, err
		}
		sec.AdminPassword, REDACTED = REDACTED, ""
		if err := store.Save(sec); err != nil {
			return ProvisionResult{}, err
		}
		c = newClient(baseURL, "admin", REDACTED)
	}
	res := ProvisionResult{}
	var eula struct {
		Accepted   bool   `json:"accepted"`
		Disclaimer string `json:"disclaimer"`
	}
	st, err := c.do(ctx, "read EULA", "GET", pathEULA, "", nil, &eula)
	if err != nil {
		return res, err
	}
	if st == 200 {
		if !eula.Accepted {
			if !p.AcceptEULA {
				return res, &BenchError{Kind: ProvisionFailed, Cause: "the EULA is not accepted", Check: "set NEXUS_BENCH_ACCEPT_EULA=yes"}
			}
			if _, err := c.do(ctx, "accept EULA", "POST", pathEULA, "", map[string]any{"accepted": true, "disclaimer": eula.Disclaimer}, nil); err != nil {
				return res, err
			}
		}
		res.EULAAccepted = true
	}
	if _, err := c.do(ctx, "set realms", "PUT", pathRealms, "", []string{"NexusAuthenticatingRealm", "DockerToken"}, nil); err != nil {
		return res, err
	}
	if _, err := c.do(ctx, "set anonymous", "PUT", pathAnonymous, "", map[string]any{"enabled": p.Anonymous, "userId": "anonymous", "realmName": "NexusAuthorizingRealm"}, nil); err != nil {
		return res, err
	}
	upsert := func(op, getPath, postPath, putPath string, body any) error {
		st, err := c.do(ctx, "read "+op, "GET", getPath, "", nil, nil)
		if err != nil {
			return err
		}
		if st == 404 {
			_, err = c.do(ctx, "create "+op, "POST", postPath, "", body, nil)
		} else {
			_, err = c.do(ctx, "update "+op, "PUT", putPath, "", body, nil)
		}
		return err
	}
	role := map[string]any{"id": "bench-docker-pull", "name": "bench-docker-pull", "description": "bench pull", "privileges": []string{"nx-repository-view-docker-*-browse", "nx-repository-view-docker-*-read"}, "roles": []string{}}
	if err := upsert("role", pathRoles+"/bench-docker-pull", pathRoles, pathRoles+"/bench-docker-pull", role); err != nil {
		return res, err
	}
	var users []map[string]any
	if _, err := c.do(ctx, "read user", "GET", pathUsers+"?userId=bench-pull", "", nil, &users); err != nil {
		return res, err
	}
	exists := false
	for _, u := range users {
		if u["userId"] == "bench-pull" {
			exists = true
		}
	}
	if sec.PullPassword == "" {
		sec.PullPassword = genPW()
		if err := store.Save(sec); err != nil {
			return res, err
		}
	}
	user := map[string]any{"userId": "bench-pull", "firstName": "Bench", "lastName": "Pull", "emailAddress": "bench-pull@example.invalid", "status": "active", "roles": []string{"bench-docker-pull"}}
	if exists {
		if _, err := c.do(ctx, "update user", "PUT", pathUsers+"/bench-pull", "", user, nil); err != nil {
			return res, err
		}
		if _, err := c.do(ctx, "set user password", "PUT", pathUsers+"/bench-pull/change-password", "text/plain", sec.PullPassword, nil); err != nil {
			return res, err
		}
	} else {
		user["password"] = sec.PullPassword
		if _, err := c.do(ctx, "create user", "POST", pathUsers, "", user, nil); err != nil {
			return res, err
		}
	}
	var blobs []map[string]any
	if _, err := c.do(ctx, "read blob stores", "GET", pathBlobStores, "", nil, &blobs); err != nil {
		return res, err
	}
	has := false
	for _, b := range blobs {
		if b["name"] == "default" {
			has = true
		}
	}
	if !has {
		return res, &BenchError{Kind: ProvisionFailed, Cause: "the default blob store is missing", Check: "kubectl logs"}
	}
	common := func(name string) map[string]any {
		return map[string]any{"name": name, "online": true,
			"storage": map[string]any{"blobStoreName": "default", "strictContentTypeValidation": true, "writePolicy": "ALLOW"},
			"docker":  map[string]any{"v1Enabled": false, "forceBasicAuth": false}}
	}
	hosted := common("docker-hosted")
	proxy := common("docker-proxy")
	proxy["proxy"] = map[string]any{"remoteUrl": p.UpstreamURL, "contentMaxAge": 1440, "metadataMaxAge": 1440}
	proxy["dockerProxy"] = map[string]any{"indexType": "REGISTRY"}
	group := common("docker-group")
	group["group"] = map[string]any{"memberNames": []string{"docker-hosted", "docker-proxy"}}
	group["docker"].(map[string]any)["httpPort"] = 8082
	for _, r := range []struct {
		kind, name string
		cfg        any
	}{{"hosted", "docker-hosted", hosted}, {"proxy", "docker-proxy", proxy}, {"group", "docker-group", group}} {
		if err := upsert("repository "+r.name, repoPath(r.kind, r.name), repoPath(r.kind, ""), repoPath(r.kind, r.name), r.cfg); err != nil {
			return res, err
		}
	}
	if _, err := c.do(ctx, "read status", "GET", pathStatus, "", nil, nil); err != nil {
		return res, err
	}
	if sv := c.header.Get("Server"); strings.HasPrefix(sv, "Nexus/") {
		v := strings.TrimPrefix(sv, "Nexus/")
		if i := strings.Index(v, " ("); i > 0 {
			res.Edition = strings.TrimSuffix(v[i+2:], ")")
			v = v[:i]
		}
		res.NexusVersion = v
	} else {
		var sw struct{ Info struct{ Version string } }
		if _, err := c.do(ctx, "read swagger", "GET", pathSwagger, "", nil, &sw); err != nil {
			return res, err
		}
		res.NexusVersion = sw.Info.Version
	}
	return res, nil
}
